head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "a1",
        "col2": "a1"
    }, {
        "col1": "a2",
        "col2": "a2"
    }, {
        "col1": "a3",
        "col2": "a3"
    }, {
        "col1": "a4",
        "col2": "a4"
    }, {
        "col1": "a5",
        "col2": "a5"
    }, {
        "col1": "a6",
        "col2": "a6"
    }];
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.checkLayout = function() {
    var topAtComplete = parseInt(WebSquare.wUnit.getJq("#autoComplete1_gridViewItemTable").css("top"));
    var heightAtComplete = parseInt(WebSquare.wUnit.getJq("#autoComplete1_gridViewItemTable").css("height"));
    var topBox = parseInt(WebSquare.wUnit.getJq("#autoComplete1").css("top"));
    var widthAt = parseInt(WebSquare.wUnit.getJq("#autoComplete1_gridViewItemTable").css("width"));
    var widthBox = parseInt(WebSquare.wUnit.getJq("#autoComplete1").css("width"));
    return Math.abs(heightAtComplete + topAtComplete - topBox) < 5 && Math.abs(widthBox - widthAt) < 10;
}
scwin.checkLayout2 = function() {
    var topAtComplete = parseInt(WebSquare.wUnit.getJq("#sel1_gridViewItemTable").css("top"));
    var heightAtComplete = parseInt(WebSquare.wUnit.getJq("#sel1_gridViewItemTable").css("height"));
    var topBox = parseInt(WebSquare.wUnit.getJq("#sel1").css("top"));
    var widthAt = parseInt(WebSquare.wUnit.getJq("#sel1_gridViewItemTable").css("width"));
    var widthBox = parseInt(WebSquare.wUnit.getJq("#sel1").css("width"));
    return topBox >= (heightAtComplete + topAtComplete) && Math.abs(widthBox - widthAt) < 10;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 'autoComplete'의 아이템목록(역삼각형)을 클릭하여 autoComplete위로 동일한 가로size의 넓이로 보여지는지 확인한다.
    //1. After running the sample, click on the list of items (inverted triangle) in 'autoComplete' and make sure that it shows up to the same width size on autoComplete.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('autoComplete1_button').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 1. 아이템목록이 autoComplete위로 동일한 가로size의 넓이로 보여진다.(이전에는 좁은 size로 보여짐)
    //1. The list of items is displayed on the autoComplete with the same width size (previously shown as a narrower size).
    WebSquare.wUnit.addCommand("assert", "scwin.checkLayout()", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Test step 2. 'selectbox'의 아이템목록(역삼각형)을 클릭하여 selectbox 위로 동일한 가로size의 넓이로 보여지는지 확인한다.
    //2. Click on the list of items in the 'selectbox' (inverted triangle) to make sure that it is visible on the selectbox at the same width.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('sel1_button').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 2. 아이템목록이 selectbox위로 동일한 가로size의 넓이로 보여진다.(이전에는 좁은 size로 보여짐)
    //2. The list of items is displayed on the selectbox with the same width size (previously shown as a narrower size).
    WebSquare.wUnit.addCommand("assert", "scwin.checkLayout2()", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 03-Apr-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
